"""kitchen-display 3.0.0: shows the orders on the screen in the kitchen. Do not edit this file.

It reads display.json. Your display.json was written for kitchen-display 2.1.
Run: python display.py --help
"""
import argparse
import base64
import json
import sys
import warnings
from pathlib import Path

VERSION = "3.0.0"
HERE = Path(__file__).resolve().parent


def word(text):
    return base64.b64decode(text).decode()


def main():
    parser = argparse.ArgumentParser(prog="display.py", description=f"kitchen-display {VERSION}")
    parser.add_argument("--mode", choices=["window", "full"], default="window",
                        help="how to show the orders (default: %(default)s)")
    args, unknown = parser.parse_known_args()
    if unknown:
        sys.exit(f"Error: unknown option {unknown[0]}. See CHANGELOG.md.")
    print(f"kitchen-display {VERSION}")
    if args.mode != "full":
        print("注文が小さなウィンドウに表示されています。キッチンは、前と同じように画面いっぱいに表示してほしいそうです。")
        sys.exit("まだです: 注文を画面いっぱいに表示してください。")
    print("Showing the orders on the whole screen. Code word (screen):", word("c2lnbmFs"))

    try:
        settings = json.loads((HERE / "display.json").read_text(encoding="utf-8"))
    except ValueError as err:
        sys.exit(f"display.json is broken: {err}")
    if "beep" in settings:
        sys.exit("Error: the setting 'beep' was removed in 3.0.0. See CHANGELOG.md.")
    if "font" in settings:
        sys.exit("Error: unknown setting 'font'. See CHANGELOG.md.")
    if settings.get("sound", "off") not in ("on", "off"):
        sys.exit("Error: 'sound' must be \"on\" or \"off\".")
    if settings.get("sound") != "on":
        sys.exit("まだです: 前と同じ動きにしてください。前の設定では、ディスプレイは音を鳴らしていました。")
    if settings.get("font_size") != "large":
        sys.exit("まだです: 文字の大きさを前と同じにしてください。")
    print("Settings loaded. Code word (settings):", word("YnJpZGdl"))

    if "refresh" in settings:
        warnings.warn("'refresh' is deprecated since 3.0.0 and will be removed in 4.0.0. "
                      "Use 'refresh_ms' instead. See MIGRATION.md.", DeprecationWarning)
        return 0
    rate = settings.get("refresh_ms")
    if rate is None:
        sys.exit("Error: set 'refresh_ms'. See MIGRATION.md.")
    if rate != 30000:
        sys.exit(f"まだです: refresh_ms = {rate} だと、画面は {rate / 1000:g} 秒ごとに更新されます。"
                 "前は30秒ごとでした。MIGRATION.md を読みましょう。")
    print("No warnings. Code word (no warnings):", word("Z2xpZGVy"))
    return 0


if __name__ == "__main__":
    warnings.simplefilter("default")
    sys.exit(main())
